from crownbench import *
import csv, collections

def report():
    rounds = {r: json.load(open(P / f'RESULTS_{r}.json')) for r in ['R1', 'R2'] if (P / f'RESULTS_{r}.json').exists()}
    if not rounds:
        return
    details = []
    csvrows = []
    for (name, res) in rounds.items():
        for row in res['tables']:
            csvrows.append(dict(round=name, **row))
    fields = ['round', 'jaw', 'tooth_type', 'method', 'teeth', 'patients', 'surface_rms_mm', 'surface_p95_mm', 'occlusal_p95_mm', 'proximal_gap_error_mm', 'proximal_patch_p95_mm', 'contact_location_mm']
    with open(P / 'TABLES.csv', 'w', newline='') as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        w.writerows(csvrows)
    with open(P / 'PER_TOOTH.csv', 'w', newline='') as f:
        cols = ['round', 'case', 'jaw', 'fdi', 'tooth_type', 'method'] + list(fields[6:])
        w = csv.DictWriter(f, fieldnames=cols)
        w.writeheader()
        for rn in rounds:
            for row in map(json.loads, open(P / f'RAW_METRICS_{rn}.jsonl')):
                for (m, vals) in row['metrics'].items():
                    w.writerow(dict(round=rn, case=row['case'], jaw=row['jaw'], fdi=row['fdi'], tooth_type=row['tooth_type'], method=m, **{q: vals[q] for q in fields[6:]}))
    res = {'schema': 'X3-crown-benchmark-delivery-v1', 'created_utc': now(), 'external_referent': json.load(open(P / 'PREREG_R1.json'))['external_referent'], 'rounds': rounds, 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'independent_review_completed': False, 'licensing': 'Authors challenge repo states CC BY-NC-ND4.0; project website footer CC BY-SA is website license. Dataset-paper/local historical statements differ; see SOURCE_LITERATURE.json. No data publication performed.', 'geometry_units': 'provisional mm; no embedded physical calibration object', 'antagonist_contact': 'UNKNOWN_NO_VERIFIED_BITE_TRANSFORM', 'executed_published_models': [], 'published_model_comparison': 'No CrownGen/MADCrowner claim; local model weights not supplied. Their papers motivate metrics/context only.', 'source_discovery_and_labor_cost': 'UNKNOWN; all measured computational stages reported, no labor/token estimates invented', 'baseline_timing_limitation': 'Raw R1 baseline details seconds=0.0 are placeholders for unmeasured standalone mirror/prior extraction, not measured zero-cost evidence; total generation wall time measured; shared-fit cost belongs to each standalone contextual method.', 'large_data_directory': str(DATA), 'large_data_bytes': disk_guard(), 'artifacts': []}
    for pattern in ['model/*.npz', 'predictions/*/*/*.npz', 'predictions/*/INDEX.json', 'public/*_INDEX.json', 'hidden/*_INDEX.json']:
        for p in DATA.glob(pattern):
            res['artifacts'].append({'path': str(p), 'bytes': p.stat().st_size, 'sha256': sha(p)})
    inversions = {}
    for rn in rounds:
        rows = list(map(json.loads, open(P / f'RAW_METRICS_{rn}.jsonl')))
        method = 'neighbor_sdf' if rn == 'R1' else 'ring_sdf'
        both = [r for r in rows if method in r['metrics'] and 'mirror' in r['metrics']]
        flips = sum(((r['metrics'][method]['surface_rms_mm'] < r['metrics']['mirror']['surface_rms_mm']) != (r['metrics'][method]['occlusal_p95_mm'] < r['metrics']['mirror']['occlusal_p95_mm']) for r in both))
        inv = {'paired_teeth': len(both), 'RMS_vs_occlusal_ranking_disagreements': flips, 'definition': 'candidate vs mirror preferred method reverses between whole-surface RMS and topbandp95; no clinical quality is inferred'}
        inversions[rn] = inv
    res['metric_ranking_disagreements'] = inversions
    put(P / 'results.json', res)
    README = "# Leave-one -tooth-out: a real, withheld surface like reference\n\nThe idea is to compare a replacement stand with the natural tooth that was removed from a published intraoral arc. The generator gets the remaining mesh, dental labels and FDI number. The original surface is outside the input of the generator. Patients are divided prior to execution; no tooth from the test patients is used in the primer. All designer hash freezes before evaluation.\n\nRun complete the demonstration with one command:\n\n```bash\n./run_all.sh\n```\n\nThe command verifies and displays existing frozen result , or completes missing steps. For a new full rerun with the same protocol and separate outputs :\n\n```bash\n./run_all.sh --replay\n```\n\nReference is published measurement geometry from [Teeth3DS +](https://arxiv.org/abs/2210.06094), with exact filehashes in SPLIT.json . It is a naturally exposed tooth surface, not a clinical ideal crown or a proprietary fixture. Training: 16 persons; R1:12 people; R2 : 8 second reserved persons. Both jaws and four dental classes are included. Ten failure in R1 is retained in the denominator 96 . R2 failure is shown separately below.\n\nR1 adds the neighbor geometry to place a mirrored tooth ; R2 adds the remaining gingiva edge around the masked hole. Each design is compared to a direct mesh-control that receives exactly the same information and customization. The SDF grid has a 0.20 mm step. Population form is an average form of the training person's signed distance field .\n\nAll table values are person-balanced averages of the respective tooth dimensions, in provisional millimetres. Surface RMS alone can hide errors at the cup or neighbor; therefore, 95 percentile is also reported in the upper 35% of the surface and errors in a proximity region towards the neighbor. The latter is a geometric contact position/closeness measure. It is not a measured contact force or clinical contact class.\n\n"
    for (rn, rr) in rounds.items():
        d = rr['decision']
        README += f"""## {rn}: {d['decision']}\n\n{d['completed']}/{d['scheduled']} teeth, {d['test_patients']} test patients. Occlusal /incisal p95 means: candidate {d['mean_occlusal_p95_mm']:.3f}, reflection {d['mirror_mean_occlusal_p95_mm']:.3f} mm; ratio {d['ratio_to_mirror']:.3f}. Paired 95% CI for the difference: {d['paired_patient_bootstrap95ci_mm'][0]:.3f} to {d['paired_patient_bootstrap95ci_mm'][1]:.3f} mm. Neighbors: difference in local p95 error {d['paired_proximal_patch_difference_mm']:+.3f} mm.\n\n"""
        README += '| Tooth type | Method | n | Surface RMS | Upper surface p95 | Neighbour region p95 | Contact mode error |\n|---|---|---:|---:|---:|---:|---:|\n'
        for t in rr['tables']:
            if t['jaw'] == 'all' and t['tooth_type'] != 'all':
                README += f"| {t['tooth_type']} | {t['method']} | {t['teeth']} | {t['surface_rms_mm']:.3f} | {t['occlusal_p95_mm']:.3f} | {t['proximal_patch_p95_mm']:.3f} | {t['contact_location_mm']:.3f} |\n"
        README += f'\nFrozen gates : ' + ', '.join((k + '=' + v for (k, v) in d['gates'].items())) + f". Equally informed control : {d['algorithmic_comparison']}. Sensitivity checks of the error injections: {('PASS' if rr['metric_controls_all_pass'] else 'FAIL')}. RMS and upper surface p95 choose different methods in {inversions[rn]['RMS_vs_occlusal_ranking_disagreements']}/{inversions[rn]['paired_teeth']} dental comparisons.\n\n"
    README += "![ Frozen result per tooth class](benchmark_figure.png)\n\nThe complete tables per jaw / tooth type are available in TABLES.csv ; each tooth and method is available in PER_TOOTH.csv and RAW_METRICS_R *.jsonl. predictions and dataset files have hash manifest in results.json . exports/ shows a real masked test arc predictions in original coordinates, like OBJ . The surfaces have an open cervical edge; they are not ready to discharge crowns with inletlio.\n\n## Use the same test for a custom method\n\n```bash\npython3 benchmark_method.py --name my_method_v1 --command 'python3 /path/my_method.py {input} {output}'\n```\n\nInput is NPZ with `vertices` ( N, 3), `faces` (M, 3), `labels` ( N,) and `target_fdi`. All target vertices and incident triangles are gone. Output is NPZ with `vertices` , `faces` in the same coordinates. `example_method.py` is a working mirror method. Use a new method version for a new submission; the script freezes all outputhas prior to facit measurement and retains missing outputs as loss. The information limit is a research contract: the method may not read original files/hidden/. There is no operating system protection against a malicious method with the same disk access.\n\n## What does not holds\n\n- Actual occlusal contact is UNKNOWN. A patient's two jaw - ID does not certify a registered bite. No zero contact or force is found.\n- Upper 35% is a pre-registered surface region, not manually verified occlusive surfaces. The contact mode measure is the nearest geometric region, not dentist assessment.\n- OBJ coordinates are treated as millimetres, consistent with the existing dental data. A physical length calibration is missing; dimensional conclusions are conditional .\n- R2 uses a cervical print form in the synthetic wormhole. This makes the task easier than a healed extraction site and is not a measured preparation margin pair.\n- Scan, segmentation and anatomical asymmetry are included in the uncertainty of the finding. Natural dental anatomy is not automatically the best possible restoration.\n- SDF has 0,20 mm resolution and numerical design errors. It can't handle a conclusion if margins at micrometer level.\n- No prepared abutments, cement layers, materials, FEM, manufactured parts or clinical assessments are included.  CrownGen  and MADCrowner has not been run and their performance cannot be compared to this table. [ CrownGen ](https://arxiv.org/html/2512.21890v1) also uses public development data; the description of  https://arxiv.org/html/2603.04771v1 ) describes a private clinical crown/preparation dataset. The papples' contact/marginal targets justify separate measurements but do not validate our prosthetic outcomes.\n\n## Dataset license and driving environment\n\nOnly local Teeth3DS is used. [Authors challenge-repository](https://github.com/abenhamadou/3DTeethSeg_MICCAI_Challenges#license) indicates CC BY-NC-ND4.0 . Project web CC BY - SA -footer applies to the web; older local maps indicate second licenses. The contradiction is preserved in sources/ and SOURCE_LITERATURE.json . No datasets or derived dental files have been published. Code/Protocol can be tested local with the dataset the reader already has access to; formal data distribution requires loose license data. Attribution: Achraf Bone -Hamadou et al., Teeth3DS + (arXiv: 2210.06094 ).\n\nExecution uses a CPU thread, no GPU and less than 3 GB own intermediate on the games disk. Numeric packages are locked in requirements.txt . The figure runs with `python3 -s plot_figure.py` , which uses the system's NumPy1.21.5/Matplotlib3.5.1 separately from the number NumPy2.2.6 . No shared environments change. Frozen failures and exact commands are found in COMMANDS.md; they do not change the outcome gates. Independent scientific review remains.\n"
    (P / 'README_DEMO.md').write_text(README)
    summary = '# X3 — measured natural crown reconstruction\n\n'
    for (rn, rr) in rounds.items():
        summary += f'## {rn}\n\n' + json.dumps(rr['decision'], indent=2) + '\n\n' + f"Metric controls: {rr['metric_controls_all_pass']}; evaluation {rr['evaluation_seconds']:.3f}s, peak RSS {rr['peak_rss_kb'] / 1024:.1f}MiB. Complete raw metrics RAW_METRICS_{rn}.jsonl.\n\n"
    summary += 'The independent external referent is the withheld published IOS geometry, source files/hash split in SPLIT.json. Mathematical distance controls use our own fixtures and are explicitly separate. Preparation/functional contact/clinical ideality remain UNKNOWN. See README_DEMO.md for tables, scope and license limits.\n\n' + json.dumps(inversions, indent=2) + '\n'
    (P / 'RESULTS.md').write_text(summary)
    feedback = json.load(open(P / 'GRAPH_FEEDBACK.json'))
    feedback.update(outcome={r: v['decision'] for (r, v) in rounds.items()}, sha256=sha(P / 'results.json'), negative_result=any((v['decision']['decision'].startswith('NEGATIVE') for v in rounds.values())), uncertainty='Patient-cluster bootstrap CI; scanner calibration, bite pose and reference annotation uncertainty UNKNOWN', population_regime='Patient-held-out natural exposed tooth surfaces; R1 12 patients, R2 sealed8 patients; synthetic deletion masks', preregistered_gate='PREREG_R1.json and PREREG_R2.json; errors unchanged on reserve', baseline='reflection,train mean SDF,identical-information direct mesh fitting')
    put(P / 'GRAPH_FEEDBACK.json', feedback)
    print('REPORT_WRITTEN', list(rounds), flush=True)
if __name__ == '__main__':
    report()
